css:
.d-stack{display:flex;flex-direction:column;gap:8px;width:200px}
.d-row{display:block;padding:8px 12px;border:1px solid var(--line);border-radius:2px;background:var(--paper);color:var(--ink);font-size:13px;font-style:normal;animation:d-fx-fade-stagger-in 280ms var(--ease-print) both}
.d-row:nth-child(2){animation-delay:40ms}
.d-row:nth-child(3){animation-delay:80ms}
.d-again{margin-top:16px;padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--ink);font:inherit;font-size:11px;cursor:pointer;transition:border-color 120ms var(--ease-print)}
.d-again:hover{border-color:var(--ink)}
@keyframes d-fx-fade-stagger-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){.d-row{animation:none}}

init:
root => {
  const rows = Array.from(root.querySelectorAll('.d-row'));
  const replay = () => rows.forEach((r) => { r.style.animation = 'none'; void r.offsetWidth; r.style.animation = ''; });
  const btn = root.querySelector('[data-replay]');
  if (btn) btn.addEventListener('click', replay);
  replay();
}
